pm.test("HTTP status is 200", function () {
    pm.response.to.have.status(200);
});

var responseBody = pm.response.json();

pm.test("Response code is 200", function () {
    pm.expect(responseBody.responseCode).to.eql(200);
});

pm.test("Products list is not empty", function () {
    pm.expect(responseBody.products).to.be.an("array");
    pm.expect(responseBody.products).to.not.be.empty;
});

pm.test("Product contains all required fields", function () {
    const product = responseBody.products[0];

    pm.expect(product).to.have.property("id");
    pm.expect(product).to.have.property("name");
    pm.expect(product).to.have.property("price");
    pm.expect(product).to.have.property("brand");
    pm.expect(product).to.have.property("category");
});

pm.test("Product category contains category details", function () {
    const product = responseBody.products[0];

    pm.expect(product.category).to.be.an("object");
    pm.expect(product.category).to.have.property("category");
});

